import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { stores } from '../../mocks/stores';
import { commonShadow } from '../../utils/uiEffects';

export default function FindStore() {
  const [showLocationModal, setShowLocationModal] = useState(true);
  const [selectedStore, setSelectedStore] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [userCoords, setUserCoords] = useState(null);

  const handleAllowLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setUserCoords({
            lat: position.coords.latitude,
            lng: position.coords.longitude
          });
          setShowLocationModal(false);
        },
        () => {
          setUserCoords({ lat: 28.6139, lng: 77.2090 });
          setShowLocationModal(false);
        }
      );
    } else {
      setUserCoords({ lat: 28.6139, lng: 77.2090 });
      setShowLocationModal(false);
    }
  };

  const handleSkipLocation = () => {
    setUserCoords({ lat: 28.6139, lng: 77.2090 });
    setShowLocationModal(false);
  };

  const handleStoreSelect = (storeId) => {
    setSelectedStore(storeId);
    localStorage.setItem('tcr_selected_store', storeId);
    setTimeout(() => {
      if (window.REACT_APP_NAVIGATE) {
        window.REACT_APP_NAVIGATE(`/menu/${storeId}`);
      }
    }, 600);
  };

  const filteredStores = stores.filter(store =>
    store.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    store.address.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-obsidian via-cocoa to-cocoa-dark">
      {/* Location Access Modal with 3D Compass */}
      <AnimatePresence>
        {showLocationModal && (
          <motion.div
            className="fixed inset-0 z-[60] flex items-center justify-center bg-black/80"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <motion.div
              className="relative w-full max-w-lg mx-4 glass-panel-strong rounded-3xl p-12 border-2 border-gold/30"
              initial={{ scale: 0.8, y: 50 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.8, y: 50 }}
              transition={{ type: 'spring', damping: 20 }}
            >
              {/* Gold Leaf Decorative Corners */}
              <div className="absolute top-0 left-0 w-16 h-16 border-t-2 border-l-2 border-gold/40 rounded-tl-3xl"></div>
              <div className="absolute top-0 right-0 w-16 h-16 border-t-2 border-r-2 border-gold/40 rounded-tr-3xl"></div>
              <div className="absolute bottom-0 left-0 w-16 h-16 border-b-2 border-l-2 border-gold/40 rounded-bl-3xl"></div>
              <div className="absolute bottom-0 right-0 w-16 h-16 border-b-2 border-r-2 border-gold/40 rounded-br-3xl"></div>

              {/* 3D Compass Animation */}
              <div className="relative w-32 h-32 mx-auto mb-8">
                <motion.div
                  className="absolute inset-0 rounded-full bg-gradient-to-br from-gold to-gold-dark opacity-20 blur-2xl"
                  animate={{ scale: [1, 1.2, 1] }}
                  transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
                />
                <motion.div
                  className="relative w-full h-full flex items-center justify-center"
                  animate={{ rotate: 360 }}
                  transition={{ duration: 8, repeat: Infinity, ease: "linear" }}
                >
                  <i className="ri-compass-3-line text-8xl text-gold" style={{ textShadow: '0 0 40px rgba(197, 160, 33, 0.8)' }}></i>
                </motion.div>
              </div>

              <h2 className="font-syncopate text-3xl text-center text-cream mb-4 tracking-wide">
                Find Your Nearest Store
              </h2>
              <p className="font-outfit text-center text-cream/70 mb-8 leading-relaxed text-sm">
                Allow location access to discover The Chocolate Room outlets near you and check real-time inventory availability
              </p>

              <motion.button
                onClick={handleAllowLocation}
                className={`w-full py-5 bg-gradient-to-r from-gold to-gold-light text-obsidian font-syncopate font-bold text-sm tracking-wider rounded-full cursor-pointer whitespace-nowrap relative overflow-hidden group ${commonShadow}`}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
              >
                <span className="relative z-10 flex items-center justify-center gap-3">
                  <i className="ri-map-pin-line text-xl"></i>
                  ALLOW LOCATION ACCESS
                </span>
              </motion.button>

              <motion.button
                onClick={handleSkipLocation}
                className="w-full mt-4 py-3 text-cream/60 font-outfit text-sm cursor-pointer hover:text-gold transition-colors whitespace-nowrap"
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
              >
                Skip for now
              </motion.button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
      <div className="pt-24 min-h-screen">
        {/* Split Screen Layout */}
        <div className="max-w-[1920px] mx-auto px-8 py-8">
          <div className="grid lg:grid-cols-2 gap-8 h-[calc(100vh-150px)]">
            {/* Left Pane - Scrollable Store List */}
            <motion.div
              className="glass-panel rounded-3xl p-6 overflow-hidden flex flex-col border border-gold/10"
              initial={{ opacity: 0, x: -50 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.6 }}
            >
              {/* Enhanced Search Header */}
              <div className="mb-6">
                <h2 className="font-syncopate text-xl text-gold mb-4 tracking-wide">Find Your Store</h2>
                <div className="relative group">
                  <i className="ri-search-line absolute left-4 top-1/2 -translate-y-1/2 text-gold/50 group-focus-within:text-gold transition-colors text-lg"></i>
                  <input
                    type="text"
                    placeholder="Search by location or store name..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full !pl-24 pr-4 py-4 bg-cocoa-dark/50 border border-gold/20 text-cream rounded-2xl font-outfit text-sm focus:outline-none focus:border-gold/60 focus:ring-4 focus:ring-gold/10 transition-all placeholder:text-cream/30"
                  />
                  <motion.div
                    className="absolute bottom-0 left-4 right-4 h-0.5 bg-gradient-to-r from-transparent via-gold/40 to-transparent scale-x-0 group-focus-within:scale-x-100 transition-transform duration-500"
                  />
                </div>
              </div>

              <div className="flex-1 overflow-y-auto pr-2 space-y-4 custom-scrollbar">
                {filteredStores.map((store, index) => (
                  <motion.div
                    key={store.id}
                    className={`relative p-6 rounded-2xl cursor-pointer transition-all duration-300 ${selectedStore === store.id
                      ? `bg-gold/20 border-2 border-gold ${commonShadow}`
                      : 'bg-cocoa-dark/40 border border-gold/10 hover:border-gold/30 hover:bg-cocoa-dark/60'
                      }`}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.4, delay: index * 0.05 }}
                    onClick={() => handleStoreSelect(store.id)}
                    whileHover={{ scale: 1.02, x: 5 }}
                    whileTap={{ scale: 0.98 }}
                  >
                    <div className="flex items-start justify-between mb-3">
                      <div className="flex-1">
                        <h3 className="font-syncopate text-base text-cream mb-1 tracking-wide">
                          {store.name}
                        </h3>
                        <p className="font-outfit text-sm text-cream/60 leading-relaxed">
                          {store.address}
                        </p>
                      </div>
                      <div className="flex flex-col items-end gap-2 ml-4">
                        <span className="font-outfit text-sm text-gold font-semibold whitespace-nowrap">
                          {store.distance} km
                        </span>
                        <span className={`px-3 py-1 rounded-full text-xs font-outfit font-bold whitespace-nowrap ${store.status === 'open'
                          ? 'bg-green-500/20 text-green-400 border border-green-500/30'
                          : 'bg-red-500/20 text-red-400 border border-red-500/30'
                          }`}>
                          {store.status === 'open' ? 'OPEN NOW' : 'CLOSED'}
                        </span>
                      </div>
                    </div>

                    <div className="flex items-center gap-4 text-xs mb-3">
                      <div className="flex items-center gap-2">
                        <i className="ri-time-line text-gold"></i>
                        <span className="font-outfit text-cream/70 whitespace-nowrap">{store.timing}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <i className="ri-phone-line text-gold"></i>
                        <span className="font-outfit text-cream/70 whitespace-nowrap">{store.phone}</span>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      {store.types.map((type) => (
                        <span
                          key={type}
                          className="px-3 py-1 bg-gold/10 border border-gold/30 rounded-full text-xs font-outfit text-gold whitespace-nowrap"
                        >
                          <i className={`${type === 'dine-in' ? 'ri-restaurant-line' : 'ri-shopping-bag-line'} mr-1`}></i>
                          {type === 'dine-in' ? 'DINE-IN' : 'TAKEAWAY'}
                        </span>
                      ))}
                    </div>
                  </motion.div>
                ))}
              </div>
            </motion.div>

            {/* Right Pane - Dark Themed Map with Custom Gold Pins */}
            <motion.div
              className="glass-panel rounded-3xl overflow-hidden border border-gold/10"
              initial={{ opacity: 0, x: 50 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.6 }}
            >
              <iframe
                src={`https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d224346.48129763456!2d77.04417!3d28.6139!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2zMjjCsDM2JzUwLjAiTiA3N8KwMTInMzIuNCJF!5e0!3m2!1sen!2sin!4v1234567890&style=feature:all|element:geometry|color:0x0A0604&style=feature:all|element:labels.text.fill|color:0xC5A021&style=feature:all|element:labels.text.stroke|color:0x140B07&style=feature:water|element:geometry|color:0x25160F&style=feature:poi|element:geometry|color:0x140B07`}
                width="100%"
                height="100%"
                style={{ border: 0 }}
                allowFullScreen
                loading="lazy"
                referrerPolicy="no-referrer-when-downgrade"
                title="Store Locations Map"
              />
            </motion.div>
          </div>
        </div>
      </div>
    </div >
  );
}
